        counter_body: "Ask exactly what experts disagree on. Almost always it's a refinement, not a foundation. The basics of any mature field are settled; debates happen in the margins. Conflating the two manufactures doubt where there isn't any.",
        counter_example: "'Show me where they disagree. If it's the third decimal, we still know the first two. The headline conclusion is consensus.'",
