        hook: "The grammar lets you read it two ways. The speaker meant one. You assumed the other.",
        body: "Ambiguity baked into sentence structure (rather than vocabulary, which is equivocation). The same sentence has two valid grammatical parses, and the speaker exploits the gap between them. Useful for plausible deniability — they meant the inoffensive reading, you got the offensive one.",
        example: "'I shot an elephant in my pajamas' — Groucho Marx. Was the elephant in pajamas, or was the speaker? Grammar allows both. Funny in a joke, manipulative in an argument.",
        counter_hook: "Restate the sentence so it can only mean one thing.",
