        counter_example: "'Your sentence can mean A or B. Which one do you mean? Once you commit, we can talk about that one.'",
        tip: "If a sentence is suspiciously useful AND suspiciously vague, it's probably amphibolous on purpose. Disambiguate before you respond — otherwise you're responding to a sentence the speaker can later deny.",
