        body: "Phrasing that's deniable to outsiders but unambiguous to insiders. The speaker can claim 'I never said that' while the intended audience clearly heard exactly that. Used to deliver politically toxic messages with plausible deniability — common in political speech, marketing, and bad-faith debate.",
        example: "A politician uses a phrase that, to the general audience, sounds like 'protecting families'. To a specific subgroup, it's a known signal for excluding a particular group. Both interpretations are real; the speaker pretends only the first one exists.",
