        hook: "The word originally meant something else. So that's what it really means now. Languages don't agree.",
        body: "Words drift. Their current meaning is whatever current speakers use them to mean — not what their roots or 17th-century definitions said. The fallacy locks meaning to origin and treats the modern speaker's actual usage as a mistake.",
