        body: "Adverse information is introduced about the speaker before the speaker speaks, prepping the audience to dismiss whatever comes next. The actual argument arrives into a hostile reception that has nothing to do with its merits. Different from ad hominem: the personal attack comes BEFORE engagement, not in place of it.",
