        hook: "What evidence would change your mind? Nothing? Then this isn't an argument, it's a faith.",
        body: "A claim that can't be refuted by any conceivable evidence isn't a strong claim — it's an empty one. Karl Popper's bar: a real claim about the world must specify what would prove it wrong. If nothing could, the claim isn't telling you anything about reality, only about the speaker's commitment to holding it.",
        example: "Believer: 'My horoscope predicts what will happen.' Skeptic: 'It says you'll have a productive day, but you fought with your boss.' Believer: 'The productivity was internal — emotional.' Whatever happens, the horoscope is right by reinterpretation. The claim costs nothing because it forbids nothing.",
        counter_hook: "If nothing could prove you wrong, you've said nothing.",
        counter_body: "Ask the speaker, in advance, what observation would refute their claim. A good claim has a clear answer. A bad one says 'nothing — there's always an explanation'. The second is unfalsifiable; treat it as decorative, not informative.",
        counter_example: "'Tell me right now: what would I have to see, in the next six months, that would convince you you're wrong? If you can't name it, the claim isn't testable.'",
        tip: "Unfalsifiable claims feel safe to hold but tell you nothing about the world. They're a coat of paint over nothing. Demand a falsification condition for any claim that wants to be taken seriously.",
