        counter_example: "'Music is vibrations, sure. So a Beethoven sonata equals random air movement? No. There's a structure on top of the vibrations. Tell me about that.'",
        tip: "Reductive moves feel intellectual but usually serve to dismiss. Ask 'just' questions back: what does the simpler description fail to explain? That gap is what the reduction was hiding.",
