        body: "A single dramatic case is presented as if it overrides general patterns. The story is real, the emotion is genuine, but a base rate doesn't bow to anecdote. The vividness hijacks attention; the data quietly becomes invisible.",
        example: "'My uncle smoked three packs a day and lived to 95.' True. Statistically irrelevant. The smoker who died at 50 has the same anecdotal force, multiplied by hundreds of thousands. The base rate hasn't moved.",
        counter_hook: "One story isn't a sample. It's a story.",
