        body: "Absence of mention is treated as evidence — usually evidence of conspiracy, or of the speaker's pet conclusion. But people don't mention countless things. Most silences mean: the topic didn't come up, wasn't relevant, was forgotten, or wasn't known. Inferring conclusions from silence requires knowing the silence is meaningful — which is exactly what's missing.",
        example: "'The newspaper didn't cover this story, so they're suppressing it.' Or: they didn't have the resources, or judged it not newsworthy, or covered it last week, or never heard of it. Suppression is just one of many possible reasons for silence — and usually the least likely.",
