        hook: "We named a category. Now we treat it like a thing. Categories don't have agency.",
        body: "An abstract concept is treated as if it were a concrete entity with its own will. 'The market hates this.' 'History will judge.' 'Society demands.' Markets don't hate, history doesn't judge, society doesn't demand — those are aggregations of decisions made by people. Reification papers over the question of who, exactly.",
