        counter_example: "'Restate that without metaphor. What's the actual claim, in concrete words? If there isn't one, it was a vibe, not a thought.'",
        tip: "Real depth survives translation. Fake depth depends on the original wording for its effect. The test: does it still sound deep when said plainly? If no, it never was.",
