        body: "An action is justified by pointing to a similar action by an opponent. The justification doesn't make either action right; it just argues for symmetry of bad behaviour. Distinct from tu quoque, which says the accuser's own behaviour disqualifies them from accusing — this one uses precedent to license the same wrong.",
