        hook: "Don't act now. Wait for more information. The information never comes; the inaction does.",
        body: "Decisions are deferred indefinitely under the guise of needing more data. Often dressed up as caution or rigor; functions as a way to avoid commitment. Real prudence has a stopping rule — 'I'll decide when X is known.' This fallacy has no stopping rule. The waiting is the position.",
