        counter_example: "'You want more data — fine. What level of certainty are you waiting for? When that's met, will you decide? If you can't say, you're not deciding later, you're refusing now.'",
        tip: "The cost of waiting is invisible — it shows up as the harms that accumulated while you delayed. Always include 'cost of inaction' in any decision; otherwise stalling looks free.",
