        body: "An online debating tactic where the questioner adopts an air of civility while demanding endless evidence, citations, and explanations — usually for points already widely accepted. The cost is dumped on the responder; the questioner contributes nothing. Refusing to answer makes the responder look rude. Continuing exhausts them.",
