        counter_body: "Acknowledge the story is real, then ask what we'd see if we zoomed out. What's the rate? The control group? The base rate of the same outcome among non-smokers? The story doesn't change at the level of the individual — but the conclusion does, dramatically.",
        counter_example: "'Your grandfather is real, and he beat the odds — that's worth noting. But for every story like his there are statistics from 60 million people. Policy has to follow the population, not the outlier.'",
        tip: "When someone leads with 'I knew a guy who…', the conclusion is almost always weaker than they think. Personal experience is data of size n=1. Inform your gut from it. Don't overrule the world with it.",
