        body: 'Проводится сравнение между случаями, которые расходятся именно по тем измерениям, что важны. Форма аналогии несёт убедительность, суть — нет. Хорошие аналогии выдерживают, когда ты прописываешь, что общего и что различно. Плохие рушатся в тот момент, когда ты это делаешь.',
