        example: "'Successful entrepreneurs wake up at 5am. Look at this list. So if I wake up at 5am, I'll be successful.' Waking early is consistent with success — and also with insomnia, anxiety, and night-shift jobs. The arrow doesn't reverse just because it's flattering.",
