        counter_body: "Restate what the implication actually says. 'If P, then Q' means: when P happens, Q follows. It doesn't say Q only happens because of P. Ask what other causes could produce Q. Almost always there are several, and the chosen P isn't even the most common one.",
        counter_example: "'You're saying: successful people do X, so doing X will make me successful. But unsuccessful people also do X — many of them. The behaviour doesn't separate the two groups, so doing it changes nothing.'",
