        body: 'Готовый фразеологический шаблон с одной-двумя ячейками заполняется новыми словами и подаётся как откровение. Шаблон несёт узнаваемость и ритм; содержание — клише, которое было до него. «X — это новая Y». «В космосе никто не услышит твой Х». «Они пришли за Х, а я молчал». Форма срабатывает на слух раньше, чем ум догоняет.',
