        example: "'I've been late to the gym every Tuesday for three months because of work. But I'm sure I'm not really avoiding it — that's just been the schedule.' The pattern is the data. Three months of perfectly aligned 'just happenings' is exactly what avoidance looks like from the inside.",
        counter_hook: "Coincidence is real. So is the habit of calling everything coincidence.",
        counter_body: "Count. If the pattern repeats, the burden flips: it's now on the speaker to show why this many same-direction events are random. A few are; many aren't. Ask what the alternative explanation predicts and whether it would produce this kind of streak by chance.",
