        body: "A statement is offered as explanation but says nothing the premise didn't already say. The structure of an argument — premise, reasoning, conclusion — is preserved; the content collapses into a restatement. 'It works because it works.' 'They lost because they didn't win.' The form looks like reasoning. Underneath, no work is done.",
