        counter_example: "'You're saying we do it this way because that's the way we do it. That's circular. The question is why this way is better than the alternative. What's the actual case?'",
        tip: "When a sentence sounds profound and remains profound after you swap synonyms in, it's probably tautological. Real claims become more or less plausible under paraphrase. Tautologies just rotate.",
