        body: "A claim is treated as established by the manner of its delivery rather than by evidence. Repetition, certainty, and rhetorical polish stand in for justification. The audience is meant to be persuaded by the performance — and a forceful 'obviously' does most of the work an argument should be doing.",
        example: "'It is patently obvious to any thinking person that this policy will work.' Patent obviousness is not a property of policies; it's a tone. The sentence asserts that disagreement is unthinkable, which is a way of skipping the thinking.",
