        body: "An uncontroversial premise or proposal serves as the carrier for a contested one packaged inside it. The audience approves the surface; the substance rides in unseen. The technique works in policy ('this jobs bill includes a small change to surveillance law…'), in arguments ('if you agree X, then surely Y'), and in negotiations where the headline term is bait for the buried clause.",
