        counter_hook: "True premise, broken inference.",
        counter_body: "Accept the fact, isolate the inference. State plainly: 'yes, that's accurate. The conclusion you're drawing from it is the question.' Then ask what the link is. The lonely fact loses its rhetorical power as soon as it's separated from the leap it's supporting.",
